import{bV as a,aL as d,u as t,G as o}from"./chunks/framework.DvBUyM1S.js";const h=JSON.parse('{"title":"Vue父子组件的生命周期","description":"","frontmatter":{"title":"Vue父子组件的生命周期","date":"2022-02-16T23:39:27.000Z","permalink":"/pages/40f989/","categories":["Vue2"],"tags":[null]},"headers":[],"relativePath":"02.开发/07.Vue2/04.Vue父子组件的生命周期.md","filePath":"02.开发/07.Vue2/04.Vue父子组件的生命周期.md","lastUpdated":1652078909000}'),s={name:"02.开发/07.Vue2/04.Vue父子组件的生命周期.md"};function i(c,e,n,l,r,p){return d(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="vue父子组件的生命周期" tabindex="-1">Vue父子组件的生命周期 <a class="header-anchor" href="#vue父子组件的生命周期" aria-label="Permalink to &quot;Vue父子组件的生命周期&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>在单个组件中，钩子的执行顺序是<code>beforeCreate-&gt; created -&gt; mounted-&gt;... -&gt;destroyed</code>， 但在多个组件嵌套时，父组件和子组件各拥有各自独立的钩子函数，他们的执行顺序有是怎么样？</p><p>了解Vue生命周期钩子，就能更好理解这个问题。</p><h3 id="vue生命周期做了什么以及能做什么" tabindex="-1">Vue生命周期做了什么以及能做什么 <a class="header-anchor" href="#vue生命周期做了什么以及能做什么" aria-label="Permalink to &quot;Vue生命周期做了什么以及能做什么&quot;">​</a></h3><ul><li><code>beforeCreate</code>执行时：<code>data</code>和<code>el</code>均未初始化，值为<code>undefined</code>。</li><li><code>created</code>执行时：<code>Vue</code> 实例观察的数据对象<code>data</code>初始化，此时可以得到<code>data</code>的值，但<code>Vue</code> 实例使用的根 <code>DOM</code> 元素el还未初始化。</li><li><code>beforeMount</code> 执行时：<code>data</code>和<code>el</code>均已经初始化，但此时<code>el</code>并没有渲染进数据，<code>el</code>的值为“虚拟”的元素节点。</li><li><code>mounted</code> 执行时：此时<code>el</code>已经渲染完成并挂载到实例上</li><li><code>beforeUpdate</code>和<code>updated</code>触发时，<code>el</code>中的数据都已经渲染完成，但只有<code>updated</code>钩子被调用时候，组件<code>dom</code>才被更新。</li><li>在<code>created</code>钩子中可以对<code>data</code>数据进行操作，这个时候可以进行数据请求将返回的数据赋给<code>data</code></li><li>在<code>mounted</code>钩子对挂载的<code>dom</code>进行操作，此时，<code>DOM</code>已经被渲染到页面上。</li><li>虽然<code>updated</code>函数会在数据变化时被触发，但却不能准确的判断是那个属性值被改变，所以在实际情况中用<code>computed</code>或<code>watch</code>函数来监听属性的变化，并做一些其他的操作。</li><li>所有的生命周期钩子自动绑定 <code>this</code> 上下文到实例中，所以不能使用箭头函数来定义一个生命周期方法 (例如 <code>created: () =&gt; this.- fetchTodos())</code>,会导致<code>this</code>指向父级。</li><li>父子组件的钩子并不会等待请求返回，请求是异步的，VUE设计也不能因为请求没有响应而不执行后面的钩子。所以，我们必须通过<code>v-if</code>来控制子组件钩子的执行时机。</li><li>在使用<code>vue-router</code>时有时需要使用来缓存组件状态，这个时候<code>created</code>钩子就不会被重复调用了，如果我们的子组件需要在每次加载或切换状态的时候进行某些操作，可以使用<code>activated</code>钩子触发。</li></ul><blockquote><p>activated, deactivated 是组件keep-alive时独有的钩子</p></blockquote><p>所以父组件会先执行到<code>beforeMount</code>，接着会执行子组件钩子到挂载结束，再挂载父组件。</p><p><strong>Vue父子组件渲染过程</strong></p><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">父beforeCreate -&gt; 父created-&gt; 父beforeMount -&gt; </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">子beforeCreate -&gt; 子created -&gt; 子beforeMount -&gt; 子mounted-&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">父mounted</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>子组件更新过程</strong></p><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">父beforeUpdate -&gt; 子beforeUpdate -&gt; 子updated -&gt; 父updated</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>父组件更新过程</strong></p><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">父beforeUpdate -&gt; 父updated</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>销毁过程</strong></p><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">父beforeDestroy -&gt; 子beforeDestroy -&gt; 子destroyed -&gt; 父destroyed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,16)])])}const b=a(s,[["render",i]]);export{h as __pageData,b as default};
